ALTER TABLE campaigns ADD COLUMN reply_count INTEGER NOT NULL DEFAULT 0 CHECK(reply_count>=0);
ALTER TABLE campaign_deliveries ADD COLUMN first_reply_at TEXT;
ALTER TABLE plan_open_metrics ADD COLUMN delivery_count INTEGER NOT NULL DEFAULT 0 CHECK(delivery_count>=0);
ALTER TABLE plan_open_metrics ADD COLUMN reply_count INTEGER NOT NULL DEFAULT 0 CHECK(reply_count>=0);
ALTER TABLE campaign_plan_open_metrics ADD COLUMN delivery_count INTEGER NOT NULL DEFAULT 0 CHECK(delivery_count>=0);
ALTER TABLE campaign_plan_open_metrics ADD COLUMN reply_count INTEGER NOT NULL DEFAULT 0 CHECK(reply_count>=0);
-- Attribute existing inbound messages once; repeat reads use rollups only.
CREATE TABLE _reply_backfill AS SELECT m.time,(SELECT d.id FROM threads t JOIN leads l ON l.email=t.email JOIN campaign_deliveries d INDEXED BY idx_delivery_lead_history ON d.lead_id=l.id WHERE t.id=m.thread_id AND d.account_id=t.account_id AND d.status IN('sent','sending','uncertain') AND COALESCE(d.sent_at,d.started_at)<=m.time AND (t.id=d.id OR instr(m.in_reply_to||m.references_json,'<'||d.id||'@relay-mail-dashboard.pages.dev>')>0 OR EXISTS(SELECT 1 FROM messages original WHERE original.message_id='<'||d.id||'@relay-mail-dashboard.pages.dev>' AND original.thread_id=t.id)) ORDER BY CASE WHEN instr(m.in_reply_to||m.references_json,'<'||d.id||'@relay-mail-dashboard.pages.dev>')>0 THEN 0 WHEN t.id=d.id THEN 1 ELSE 2 END,COALESCE(d.sent_at,d.started_at) DESC,d.id DESC LIMIT 1) AS delivery_id FROM messages m WHERE m.direction='in';
UPDATE campaign_deliveries SET first_reply_at=b.first_reply FROM (SELECT delivery_id,MIN(time) AS first_reply FROM _reply_backfill WHERE delivery_id IS NOT NULL GROUP BY delivery_id) b WHERE campaign_deliveries.id=b.delivery_id;
DROP TABLE _reply_backfill;
UPDATE campaigns SET reply_count=(SELECT COUNT(*) FROM campaign_deliveries d WHERE d.campaign_id=campaigns.id AND d.status='sent' AND d.first_reply_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM delivery_bounces b WHERE b.delivery_id=d.id));
INSERT INTO plan_open_metrics(template_id,delivery_count,reply_count) SELECT COALESCE(d.template_id,c.template_id),COUNT(*),SUM(d.first_reply_at IS NOT NULL) FROM campaign_deliveries d JOIN campaigns c ON c.id=d.campaign_id WHERE d.status='sent' AND NOT EXISTS(SELECT 1 FROM delivery_bounces b WHERE b.delivery_id=d.id) GROUP BY COALESCE(d.template_id,c.template_id) ON CONFLICT(template_id) DO UPDATE SET delivery_count=excluded.delivery_count,reply_count=excluded.reply_count;
INSERT INTO campaign_plan_open_metrics(campaign_id,template_id,delivery_count,reply_count) SELECT d.campaign_id,COALESCE(d.template_id,c.template_id),COUNT(*),SUM(d.first_reply_at IS NOT NULL) FROM campaign_deliveries d JOIN campaigns c ON c.id=d.campaign_id WHERE d.status='sent' AND NOT EXISTS(SELECT 1 FROM delivery_bounces b WHERE b.delivery_id=d.id) GROUP BY d.campaign_id,COALESCE(d.template_id,c.template_id) ON CONFLICT(campaign_id,template_id) DO UPDATE SET delivery_count=excluded.delivery_count,reply_count=excluded.reply_count;
CREATE TRIGGER reply_delivery_status AFTER UPDATE OF status ON campaign_deliveries WHEN NEW.status<>OLD.status AND (NEW.status='sent' OR OLD.status='sent') AND NOT EXISTS(SELECT 1 FROM delivery_bounces WHERE delivery_id=NEW.id) BEGIN
INSERT OR IGNORE INTO plan_open_metrics(template_id) VALUES(COALESCE(NEW.template_id,(SELECT template_id FROM campaigns WHERE id=NEW.campaign_id)));
INSERT OR IGNORE INTO campaign_plan_open_metrics(campaign_id,template_id) VALUES(NEW.campaign_id,COALESCE(NEW.template_id,(SELECT template_id FROM campaigns WHERE id=NEW.campaign_id)));
UPDATE plan_open_metrics SET delivery_count=delivery_count+((NEW.status='sent')-(OLD.status='sent')),reply_count=reply_count+((NEW.status='sent')-(OLD.status='sent'))*(NEW.first_reply_at IS NOT NULL) WHERE template_id=COALESCE(NEW.template_id,(SELECT template_id FROM campaigns WHERE id=NEW.campaign_id));
UPDATE campaign_plan_open_metrics SET delivery_count=delivery_count+((NEW.status='sent')-(OLD.status='sent')),reply_count=reply_count+((NEW.status='sent')-(OLD.status='sent'))*(NEW.first_reply_at IS NOT NULL) WHERE campaign_id=NEW.campaign_id AND template_id=COALESCE(NEW.template_id,(SELECT template_id FROM campaigns WHERE id=NEW.campaign_id));
UPDATE campaigns SET reply_count=reply_count+((NEW.status='sent')-(OLD.status='sent')) WHERE id=NEW.campaign_id AND NEW.first_reply_at IS NOT NULL;
END;
CREATE TRIGGER reply_first_message AFTER UPDATE OF first_reply_at ON campaign_deliveries WHEN OLD.first_reply_at IS NULL AND NEW.first_reply_at IS NOT NULL AND NEW.status='sent' AND NOT EXISTS(SELECT 1 FROM delivery_bounces WHERE delivery_id=NEW.id) BEGIN
UPDATE campaigns SET reply_count=reply_count+1 WHERE id=NEW.campaign_id;
UPDATE plan_open_metrics SET reply_count=reply_count+1 WHERE template_id=COALESCE(NEW.template_id,(SELECT template_id FROM campaigns WHERE id=NEW.campaign_id));
UPDATE campaign_plan_open_metrics SET reply_count=reply_count+1 WHERE campaign_id=NEW.campaign_id AND template_id=COALESCE(NEW.template_id,(SELECT template_id FROM campaigns WHERE id=NEW.campaign_id));
END;
CREATE TRIGGER reply_inbound_insert AFTER INSERT ON messages WHEN NEW.direction='in' BEGIN UPDATE campaign_deliveries SET first_reply_at=NEW.time WHERE id=(SELECT d.id FROM threads t JOIN leads l ON l.email=t.email JOIN campaign_deliveries d INDEXED BY idx_delivery_lead_history ON d.lead_id=l.id WHERE t.id=NEW.thread_id AND d.account_id=t.account_id AND d.status IN('sent','sending','uncertain') AND COALESCE(d.sent_at,d.started_at)<=NEW.time AND (t.id=d.id OR instr(NEW.in_reply_to||NEW.references_json,'<'||d.id||'@relay-mail-dashboard.pages.dev>')>0 OR EXISTS(SELECT 1 FROM messages original WHERE original.message_id='<'||d.id||'@relay-mail-dashboard.pages.dev>' AND original.thread_id=t.id)) ORDER BY CASE WHEN instr(NEW.in_reply_to||NEW.references_json,'<'||d.id||'@relay-mail-dashboard.pages.dev>')>0 THEN 0 WHEN t.id=d.id THEN 1 ELSE 2 END,COALESCE(d.sent_at,d.started_at) DESC,d.id DESC LIMIT 1) AND first_reply_at IS NULL; END;
CREATE TRIGGER reply_inbound_move AFTER UPDATE OF thread_id ON messages WHEN NEW.direction='in' AND NEW.thread_id<>OLD.thread_id BEGIN UPDATE campaign_deliveries SET first_reply_at=NEW.time WHERE id=(SELECT d.id FROM threads t JOIN leads l ON l.email=t.email JOIN campaign_deliveries d INDEXED BY idx_delivery_lead_history ON d.lead_id=l.id WHERE t.id=NEW.thread_id AND d.account_id=t.account_id AND d.status IN('sent','sending','uncertain') AND COALESCE(d.sent_at,d.started_at)<=NEW.time AND (t.id=d.id OR instr(NEW.in_reply_to||NEW.references_json,'<'||d.id||'@relay-mail-dashboard.pages.dev>')>0 OR EXISTS(SELECT 1 FROM messages original WHERE original.message_id='<'||d.id||'@relay-mail-dashboard.pages.dev>' AND original.thread_id=t.id)) ORDER BY CASE WHEN instr(NEW.in_reply_to||NEW.references_json,'<'||d.id||'@relay-mail-dashboard.pages.dev>')>0 THEN 0 WHEN t.id=d.id THEN 1 ELSE 2 END,COALESCE(d.sent_at,d.started_at) DESC,d.id DESC LIMIT 1) AND first_reply_at IS NULL; END;
CREATE TRIGGER reply_bounce AFTER INSERT ON delivery_bounces WHEN (SELECT status FROM campaign_deliveries WHERE id=NEW.delivery_id)='sent' BEGIN
UPDATE campaigns SET reply_count=reply_count-(SELECT first_reply_at IS NOT NULL FROM campaign_deliveries WHERE id=NEW.delivery_id) WHERE id=NEW.campaign_id;
UPDATE plan_open_metrics SET delivery_count=delivery_count-1,reply_count=reply_count-(SELECT first_reply_at IS NOT NULL FROM campaign_deliveries WHERE id=NEW.delivery_id) WHERE template_id=(SELECT COALESCE(d.template_id,c.template_id) FROM campaign_deliveries d JOIN campaigns c ON c.id=d.campaign_id WHERE d.id=NEW.delivery_id);
UPDATE campaign_plan_open_metrics SET delivery_count=delivery_count-1,reply_count=reply_count-(SELECT first_reply_at IS NOT NULL FROM campaign_deliveries WHERE id=NEW.delivery_id) WHERE campaign_id=NEW.campaign_id AND template_id=(SELECT COALESCE(d.template_id,c.template_id) FROM campaign_deliveries d JOIN campaigns c ON c.id=d.campaign_id WHERE d.id=NEW.delivery_id);
END;
